<?php requireRole('admin'); ?><section class="hero"><h1>⚙️ Admin Dashboard</h1><p>Manage and monitor CodeBridge.</p></section><div id="stats" class="stat-grid"></div><br><div class="card"><h2>Users</h2><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>XP</th><th>Created</th></tr></thead><tbody id="users"></tbody></table></div><script>async function load(){let s=await api('backend/api/admin.php?action=stats');document.getElementById('stats').innerHTML=Object.entries(s).map(([k,v])=>`<div class="stat">${k}<strong>${v}</strong></div>`).join('');let u=await api('backend/api/admin.php?action=users');document.getElementById('users').innerHTML=u.map(x=>`<tr><td>${escapeHTML(x.full_name)}</td><td>${escapeHTML(x.email)}</td><td>${x.role}</td><td>${x.xp}</td><td>${x.created_at}</td></tr>`).join('')}load()</script>
